<?php session_start(); require '../config.php'; if(!empty($_SESSION['admin_id'])) redirect('dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){exit('Invalid request.');} $stmt=db()->prepare("SELECT * FROM admins WHERE email=? LIMIT 1"); $stmt->execute([trim($_POST['email']??'')]); $admin=$stmt->fetch(); if($admin && password_verify($_POST['password']??'',$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];$_SESSION['admin_name']=$admin['name'];redirect('dashboard.php');} $error='Invalid email or password.';} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="center"><form class="card auth" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><img src="../assets/images/school-logo.png" class="auth-logo"><h1>Admin Portal</h1><p class="error"><?=e($error)?></p><input type="email" name="email" placeholder="Admin email" required><input type="password" name="password" placeholder="Password" required><button class="btn">Login</button><a href="../index.php">← Back to website</a></form></body></html>
